        keys: List[str] = list(raw_keys) if raw_keys else []
    except Exception as err:
        logger.error("Failed to query registry keys: %s", err, exc_info=True)
        return SchemaDiagnosticReport(
            total_keys=0,
            passed_keys=0,
            failed_keys=["*REGISTRY_UNAVAILABLE*"],
            validation_results={},
            duration_ms=(time.perf_counter() - start_time) * 1000.0,
            timestamp=report_ts,
        )

    for key in keys:
        key_errors: List[str] = []
        is_valid = False
        try:
            is_valid = bool(registry.validate(key))
            if not is_valid:
                key_errors.append(f"Validator returned False for key: {key}")
        except Exception as val_err:
            key_errors.append(f"Validation raised exception: {type(val_err).__name__}: {val_err}")

        result = ValidationResult(
            is_valid=is_valid,
            errors=key_errors,
            timestamp=time.time(),
        )
        results[key] = result

        if is_valid:
            passed_count += 1
        else:
            failed_keys.append(key)

    duration_ms: float = (time.perf_counter() - start_time) * 1000.0
    return SchemaDiagnosticReport(
        total_keys=len(keys),
        passed_keys=passed_count,
        failed_keys=failed_keys,
        validation_results=results,
        duration_ms=duration_ms,
