                        val = float(s)
                        if math.isfinite(val):
                            validated.append(val)
                    except (TypeError, ValueError, OverflowError):
                        continue
        except (TypeError, ValueError):
            return []
        return validated

    @staticmethod
    def compute_stats(samples: Optional[Sequence[float]]) -> Optional[TelemetryStatsResult]:
        """
        Computes comprehensive statistical summary for a list of samples using
        numerically stable Welford's algorithm with safeguard against variance underflow.
        """
        if samples is None:
            return None
        valid_samples = TelemetryStatsEngine.validate_samples(samples)
        if not valid_samples:
            return None

        count = len(valid_samples)
        if count == 1:
            val = valid_samples[0]
            return TelemetryStatsResult(
                mean=val,
                variance=0.0,
                std_dev=0.0,
                min=val,
                max=val,
                count=1
            )

        mean = 0.0
        m2 = 0.0
        min_val = float('inf')
        max_val = float('-inf')

        try:
            for idx, x in enumerate(valid_samples, start=1):
                if x < min_val:
                    min_val = x
                if x > max_val:
                    max_val = x
                delta = x - mean
                mean += delta / idx
                delta2 = x - mean
                m2 += delta * delta2
        except (OverflowError, ArithmeticError):
            # Fallback for catastrophic numerical edge conditions
            mean = math.fsum(valid_samples) / count
            min_val = min(valid_samples)
            max_val = max(valid_samples)
            m2 = math.fsum((x - mean) ** 2 for x in valid_samples)

        variance = m2 / (count - 1) if count > 1 else 0.0
        if not math.isfinite(variance) or variance < 0.0:
            variance = 0.0
        std_dev = math.sqrt(variance)

        return TelemetryStatsResult(
            mean=mean if math.isfinite(mean) else 0.0,
            variance=variance,
            std_dev=std_dev if math.isfinite(std_dev) else 0.0,
            min=min_val if math.isfinite(min_val) else 0.0,
            max=max_val if math.isfinite(max_val) else 0.0,
            count=count
        )

    @staticmethod
    def compute_variance(samples: Optional[Sequence[float]], mean: float) -> float:
        """
        Computes sample variance using high-precision sum of squared differences.
        Guarantees non-negative result and validates finite inputs.
        """
        if (
            samples is None 
            or isinstance(mean, bool) 
            or not isinstance(mean, (int, float)) 
            or not math.isfinite(mean)
        ):
            return 0.0
        valid_samples = TelemetryStatsEngine.validate_samples(samples)
        n = len(valid_samples)
        if n < 2:
            return 0.0

        target_mean = float(mean)
        try:
            variance = math.fsum((x - target_mean) ** 2 for x in valid_samples) / (n - 1)
        except (OverflowError, ArithmeticError):
            return 0.0

        if not math.isfinite(variance) or variance < 0.0:
            return 0.0
        return variance

    @staticmethod
    def compute_moving_average(samples: Optional[Sequence[float]], window_size: int) -> List[float]:
        """
        Computes a simple moving average over a sliding window.
        Filters invalid values, prevents drift via periodic sum refreshes, and ensures bounds safety.
        """
        if (
            samples is None 
            or isinstance(window_size, bool) 
            or not isinstance(window_size, int) 
            or window_size <= 0
        ):
            return []
        valid_samples = TelemetryStatsEngine.validate_samples(samples)
        n = len(valid_samples)
        if window_size > n:
            return []

        window_f = float(window_size)
        try:
            current_sum = math.fsum(valid_samples[:window_size])
            moving_averages: List[float] = [current_sum / window_f]

            steps_since_refresh = 0
            for i in range(window_size, n):
                steps_since_refresh += 1
                if steps_since_refresh >= _MOVING_AVERAGE_RECALC_INTERVAL:
                    current_sum = math.fsum(valid_samples[i - window_size + 1 : i + 1])
                    steps_since_refresh = 0
                else:
                    current_sum += valid_samples[i] - valid_samples[i - window_size]
                avg = current_sum / window_f
                moving_averages.append(avg if math.isfinite(avg) else 0.0)
            return moving_averages
        except (OverflowError, ArithmeticError):
            return []

    @staticmethod
    def compute_percentile(samples: Optional[Sequence[float]], percentile: float) -> float:
        """Computes the Nth percentile of a dataset with linear interpolation and boundary clamping."""
        if samples is None:
            return 0.0
        valid_samples = TelemetryStatsEngine.validate_samples(samples)
        if not valid_samples:
            return 0.0
        if (
            isinstance(percentile, bool) 
            or not isinstance(percentile, (int, float)) 
            or not math.isfinite(percentile)
        ):
            percentile = 0.0
        p = max(0.0, min(100.0, float(percentile)))
        sorted_samples = sorted(valid_samples)
        n = len(sorted_samples)
        if n == 1:
            return sorted_samples[0]

        index = (n - 1) * (p / 100.0)
        lower = int(math.floor(index))
        upper = int(math.ceil(index))

        if lower >= n - 1:
            return sorted_samples[-1]
        if lower == upper:
            return sorted_samples[lower]

        weight_upper = index - lower
        result = sorted_samples[lower] * (1.0 - weight_upper) + sorted_samples[upper] * weight_upper
        return result if math.isfinite(result) else sorted_samples[lower]

    @staticmethod
    def compute_median(samples: Optional[Sequence[float]]) -> float:
        """Computes the 50th percentile (median) of the dataset."""
        return TelemetryStatsEngine.compute_percentile(samples, 50.0)

    @staticmethod
    def compute_z_score(value: float, mean: float, std_dev: float) -> float:
        """Computes the Z-score for anomaly detection with zero-division safeguard."""
        if (
            isinstance(value, bool)
            or isinstance(mean, bool)
            or isinstance(std_dev, bool)
            or not isinstance(value, (int, float))
            or not isinstance(mean, (int, float))
            or not isinstance(std_dev, (int, float))
        ):
            return 0.0
        val_f = float(value)
        mean_f = float(mean)
        std_f = float(std_dev)
        if not (math.isfinite(val_f) and math.isfinite(mean_f) and math.isfinite(std_f)):
            return 0.0
        if std_f <= _EPSILON:
            return 0.0
        try:
            score = (val_f - mean_f) / std_f
            return score if math.isfinite(score) else 0.0
        except (OverflowError, ZeroDivisionError):
            return 0.0

    @staticmethod
    def detect_outliers(samples: Optional[Sequence[float]], threshold: float = 3.0) -> List[float]:
        """Identifies values exceeding a given standard deviation threshold (Z-score)."""
        if samples is None:
            return []
        if (
            isinstance(threshold, bool)
            or not isinstance(threshold, (int, float))
            or not math.isfinite(threshold)
            or threshold < 0.0
        ):
            return []
        stats = TelemetryStatsEngine.compute_stats(samples)
        if stats is None or stats.std_dev <= _EPSILON:
            return []
        valid_samples = TelemetryStatsEngine.validate_samples(samples)
        outliers: List[float] = []
        thresh_f = float(threshold)
        for val in valid_samples:
            z = abs(TelemetryStatsEngine.compute_z_score(val, stats.mean, stats.std_dev))
            if z > thresh_f:
                outliers.append(val)
        return outliers

    @staticmethod
    def compute_exponential_moving_average(samples: Optional[Sequence[float]], alpha: float) -> List[float]:
        """
        Computes exponential moving average (EMA) with smoothing factor alpha clamped in (0, 1].
        """
        if samples is None:
            return []
        valid_samples = TelemetryStatsEngine.validate_samples(samples)
        if not valid_samples:
            return []
        if (
            isinstance(alpha, bool)
            or not isinstance(alpha, (int, float))
            or not math.isfinite(alpha)
        ):
            clamped_alpha = 0.5
        else:
            clamped_alpha = max(1e-6, min(1.0, float(alpha)))

        ema_values: List[float] = [valid_samples[0]]
        one_minus_alpha = 1.0 - clamped_alpha
        for val in valid_samples[1:]:
            try:
                ema = (clamped_alpha * val) + (one_minus_alpha * ema_values[-1])
                ema_values.append(ema if math.isfinite(ema) else ema_values[-1])
            except (OverflowError, ArithmeticError):
                ema_values.append(ema_values[-1])
        return ema_values
